months = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
          'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь']
def month_name(number):
    if not isinstance(number, int) or not 1 <= number <= 12:
        raise ValueError('Нужен целый номер месяца от 1 до 12')
    return months[number - 1]
selected_month = 3
assert month_name(selected_month) == 'Март'
try:
    month_name(0)
except ValueError:
    print('Неверный месяц отклонён')
else:
    raise AssertionError('Ноль не должен означать декабрь')
print('Месяц:', month_name(selected_month))
